	/** 
	 * jumpstart the process by instantiating2 Attestation
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		attestationId = AttestationService.getAttestationInstance()
		.createAttestation( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AttestationService.getAttestationInstance()
				.createAttestation( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.attestationSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Attestation : " + successValue.getAttestationId());
							  if (successValue.getAttestationId().equals(attestationId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAttestationList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Attestation test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on attestation consumed")
					);
			subscriber.attestationSubscribe( attestationId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Attestation : " + successValue.getAttestationId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAttestationList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on attestation for attestationId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Attestation. 
	 */
	protected Attestation read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Attestation" );

		Attestation entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Attestation with primary key" );
		msg.append( attestationId );
		
		AttestationFetchOneSummary fetchOneSummary = new AttestationFetchOneSummary( attestationId );

		try {
			entity = AttestationService.getAttestationInstance().getAttestation( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Attestation " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Attestation.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Attestation." );

		StringBuilder msg = new StringBuilder( "Failed to update a Attestation : " );        
		Attestation entity = read();
		UpdateAttestationCommand command = generateUpdateCommand();
		command.setAttestationId(entity.getAttestationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Attestation." );

			// for use later on...
			attestationId = entity.getAttestationId();

			AttestationService proxy = AttestationService.getAttestationInstance();  

			proxy.updateAttestation( command ).get();

			LOGGER.info( "-- Successfully saved Attestation - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + attestationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Attestation.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Attestation." );

		Attestation entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Attestation with id " + attestationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Attestation with id " + attestationId );

			throw e;
		}

		try{
			AttestationService.getAttestationInstance().delete( new DeleteAttestationCommand( entity.getAttestationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Attestation with id " + attestationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Attestation with id " + attestationId );

			throw e;
		}
	}

	/**
	 * get all Attestations.
	 */
	protected List<Attestation> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Attestations:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Attestation : " );        
		List<Attestation> collection  = new ArrayList<>();

		try {
			// call the static get method on the AttestationService
			collection = AttestationService.getAttestationInstance().getAllAttestation();
			assertNotNull( collection, "An Empty collection of Attestation was incorrectly returned.");
			
			// Now print out the values
			Attestation entity = null;            
			Iterator<Attestation> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAttestationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

